function who(uid){return db.users.find(u=>u.id===uid&&u.tenantId===tenantId())?.name||'—'}
function can(page){const p=PAGES[page],u=user();if(!u||!p)return false;if(page==='workbook'&&u.tenantId!=='TN-ANNUR')return false;return p[2]==='Semua'||p[2].includes(u.role)}
