function assertRole(roles){if(!user()||!roles.includes(user().role))throw Error('Aksi tidak diizinkan untuk role '+(user()?.role||'publik'))}
function aud(type,detail){db.audit.unshift({id:id('AU'),tenantId:tenantId(),at:now(),by:user()?.name||'Publik',type,detail});persist()}
function login(uid,remember=false){const u=db.users.find(x=>x.id===uid&&x.active)||db.platformAdmins?.find(x=>x.id===uid&&x.active&&x.scope==='platform');if(!u)return toast('Akun tidak tersedia','error');session={userId:uid,remember,lastActive:Date.now(),scope:u.scope||'tenant'};sessionStorage.removeItem(SESSIONKEY);localStorage.removeItem(SESSIONKEY);(remember?localStorage:sessionStorage).setItem(SESSIONKEY,JSON.stringify(session));state.page=u.scope==='platform'?'platform-admin':'dashboard';state.modal=null;render()}
function logout(){session=null;sessionStorage.removeItem(SESSIONKEY);localStorage.removeItem(SESSIONKEY);state.page='landing';state.modal=null;render()}
function touch(){if(!session)return;if(!session.remember&&Date.now()-session.lastActive>30*60*1000){logout();toast('Sesi berakhir setelah 30 menit tidak aktif','error');return}session.lastActive=Date.now();(session.remember?localStorage:sessionStorage).setItem(SESSIONKEY,JSON.stringify(session))}
setInterval(()=>{if(session&&!session.remember&&Date.now()-session.lastActive>30*60*1000){logout();toast('Sesi demo kedaluwarsa','error')}},60000);
