const tag=s=>{const cls={aktif:'ok',terverifikasi:'ok',disetujui:'ok',tersalurkan:'ok',hadir:'ok',selesai:'ok',arsip:'info',tercatat:'warn',menunggu:'warn',diajukan:'warn',pending:'warn',belum:'warn',selisih:'bad',batal:'bad',ditolak:'bad',tidak_hadir:'bad'}[s]||'info';return `<span class="tag ${cls}">${e(String(s).replaceAll('_',' '))}</span>`};
