const sel=(label,name,options,val='',extra='')=>`<div class="field"><label for="${e(name)}">${e(label)}</label><select name="${e(name)}" id="${e(name)}" ${extra}>${options.map(o=>{const v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<option value="${e(v)}" ${String(v)===String(val)?'selected':''}>${e(t)}</option>`}).join('')}</select></div>`;
const textarea=(label,name,value='')=>`<div class="field full"><label for="${e(name)}">${e(label)}</label><textarea id="${e(name)}" name="${e(name)}">${e(value)}</textarea></div>`;
const btn=(title,act,cls='',data='')=>`<button type="button" class="btn ${cls}" data-action="${act}" ${data}>${title}</button>`;
const frmBtn=(label='Simpan perubahan')=>`<div class="form-actions"><button class="btn primary" type="submit">${label}</button></div>`;
const boxhead=(title,description='',action='')=>`<div class="page-head"><div><h2>${title}</h2><p>${description}</p></div><div class="actions">${action}</div></div>`;
const TABLE_PAGE_SIZE = 10;
const tableRegistry = new Map();
const tablePageState = new Map();
const tableOccurrences = new Map();
function tablePlain(value) { return String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim() }
function tableHash(value) { let hash = 2166136261; for (let i = 0; i < value.length; i += 1) { hash ^= value.charCodeAt(i); hash = Math.imul(hash, 16777619) } return (hash >>> 0).toString(36) }
function paginateRows(rows, page = 1, pageSize = TABLE_PAGE_SIZE) {
 const size = Math.max(1, Math.floor(Number(pageSize) || TABLE_PAGE_SIZE));
 const total = Array.isArray(rows) ? rows.length : 0;
 const totalPages = Math.max(1, Math.ceil(total / size));
 const currentPage = Math.max(1, Math.min(totalPages, Math.floor(Number(page) || 1)));
 const startIndex = (currentPage - 1) * size;
 return { page: currentPage, pageSize: size, total, totalPages, startIndex, endIndex: Math.min(total, startIndex + size), rows: (Array.isArray(rows) ? rows : []).slice(startIndex, startIndex + size) };
}
function renderTableBlock(id) {
 const record = tableRegistry.get(id); if (!record) return '';
 const { headers, rows, empty } = record;
 const page = paginateRows(rows, tablePageState.get(id) || 1);
 tablePageState.set(id, page.page);
 const body = rows.length ? page.rows.map(r => `<tr>${(Array.isArray(r) ? r : [r]).map(c => `<td>${c ?? ''}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`;
 let pagination = '';
 if (page.total > TABLE_PAGE_SIZE) {
  const firstPage = Math.max(1, Math.min(page.page - 2, page.totalPages - 4));
  const lastPage = Math.min(page.totalPages, firstPage + 4);
  const pageButtons = [];
  if (firstPage > 1) pageButtons.push(`<button type="button" class="table-page-btn" data-table-page="1" aria-label="Halaman 1">1</button>${firstPage > 2 ? '<span class="table-page-ellipsis" aria-hidden="true">…</span>' : ''}`);
  for (let n = firstPage; n <= lastPage; n += 1) pageButtons.push(`<button type="button" class="table-page-btn" data-table-page="${n}" ${n === page.page ? 'aria-current="page"' : ''} aria-label="Halaman ${n}">${n}</button>`);
  if (lastPage < page.totalPages) pageButtons.push(`${lastPage < page.totalPages - 1 ? '<span class="table-page-ellipsis" aria-hidden="true">…</span>' : ''}<button type="button" class="table-page-btn" data-table-page="${page.totalPages}" aria-label="Halaman ${page.totalPages}">${page.totalPages}</button>`);
  pagination = `<nav class="table-pagination" aria-label="Navigasi halaman tabel"><div class="table-page-summary"><span>Menampilkan <b>${page.startIndex + 1}–${page.endIndex}</b> dari <b>${page.total.toLocaleString('id-ID')}</b> data</span><small>10 data per halaman</small></div><div class="table-page-controls"><button type="button" class="table-page-btn table-page-prev" data-table-page="${page.page - 1}" ${page.page === 1 ? 'disabled' : ''} aria-label="Halaman sebelumnya">‹ <span>Sebelumnya</span></button><div class="table-page-numbers">${pageButtons.join('')}</div><button type="button" class="table-page-btn table-page-next" data-table-page="${page.page + 1}" ${page.page === page.totalPages ? 'disabled' : ''} aria-label="Halaman berikutnya"><span>Selanjutnya</span> ›</button></div></nav>`;
 }
 return `<div class="table-component" data-table-component="${id}"><div class="table-wrap"><table><thead><tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>${pagination}</div>`;
}
function table(headers, rows, empty = 'Belum ada data') {
 const safeHeaders = Array.isArray(headers) ? headers : [];
 const safeRows = Array.isArray(rows) ? rows : [];
 const signature = `${state.page || 'page'}|${safeHeaders.map(tablePlain).join('\u001f')}|${safeRows.map(r => tablePlain(Array.isArray(r) ? r[0] : r)).join('\u001f')}|${safeRows.length}`;
 const baseId = `table-${tableHash(signature)}`;
 const occurrence = (tableOccurrences.get(baseId) || 0) + 1;
 tableOccurrences.set(baseId, occurrence);
 const id = `${baseId}-${occurrence}`;
 tableRegistry.set(id, { headers: safeHeaders, rows: safeRows, empty });
 return renderTableBlock(id);
}
function stat(label,value,detail,icon='◈'){return `<article class="card stat"><div class="top"><span>${label}</span><span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${detail||'Data simulasi'}</small></article>`}
const modal=(title,body,large=false)=>{state.modal={title,body,large};renderModal()};
function renderModal(){let m=document.getElementById('modal-root');if(!m)return;m.innerHTML=state.modal?`<div class="modal-backdrop" data-action="close-modal-bg"><section role="dialog" aria-modal="true" aria-label="${e(state.modal.title)}" class="modal ${state.modal.large?'large':''}"><div class="modal-head"><h3>${e(state.modal.title)}</h3><button class="close" data-action="close-modal" aria-label="Tutup">×</button></div>${state.modal.body}</section></div>`:''}
function navigate(page){if(page!=='public'&&!can(page)){toast('Tidak tersedia untuk role ini','error');return}state.page=page;state.modal=null;state.search='';render();window.scrollTo(0,0)}
function nav(){let group1=['dashboard','my-zis','transactions','muzakki','deposits','ledger','corrections','mustahik','allocation','distribution','reports','workbook'];let group2=['periods','settings','schedule','incentives','notifications','tenant','users','audit','amil-guide','prototype','help'];let make=arr=>arr.filter(can).map(k=>`<button class="nav-btn ${state.page===k?'active':''}" data-action="navigate" data-page="${k}"><span class="ic">${PAGES[k][1]}</span>${PAGES[k][0]}</button>`).join('');return `<aside class="side" id="side"><div class="brand"><img class="brand-logo" src="assets/sizisnur-logo-mark.png" alt="Logo SiZisNur"><div><b>SiZisNur</b><small>Administrasi ZIS · V3</small></div></div><div class="menu-label">Operasional Zakat</div>${make(group1)}<div class="menu-label">Manajemen & Sistem</div>${make(group2)}<div class="side-foot"><button class="sidebar-home" data-action="landing">← Beranda SiZisNur</button><br><span class="status-dot"></span> Berjalan secara lokal / offline<br>Prototype fungsional — bukan data produksi<br>© SiZisNur V3 · Demo An-Nur VPA</div></aside>`}
function shell(){tableOccurrences.clear();let u=user(),p=PAGES[state.page];if(!can(state.page))state.page=(u.role==='Muzakki'&&can('my-zis'))?'my-zis':'dashboard';if(!can(state.page))state.page='help';p=PAGES[state.page];return `<div class="shell">${nav()}<div class="workspace"><header class="topbar"><div class="actions"><button class="btn sm mobile-menu" data-action="toggle-menu">☰</button><div><div class="crumb">${e(tenant().name)} / ${e(p[0])}</div><h1>${e(p[0])}</h1></div></div><div class="top-actions"><button class="btn sm" data-action="theme">◐ Tema</button><button class="btn sm" data-action="public">◉ Publik</button><button class="btn sm" data-action="landing">Beranda Produk</button><span class="userpill"><span class="avatar">${e(u.name.charAt(0))}</span><span>${e(u.name)}<br><b>${e(u.role)}</b></span></span><button class="btn sm" data-action="logout">Keluar</button></div></header><main class="content" id="main-content">${renderPage()}</main><div class="app-footer">${e(DEMO_CAVEAT)}</div></div></div><div id="modal-root"></div>`}
function render(){document.body.classList.toggle('dark',localStorage.getItem(THEMEKEY)==='dark');const root=document.getElementById('app');if(state.page==='public'){root.innerHTML=publicView(!!user())+'<div id="modal-root"></div>';renderModal();return}if(state.page==='landing'){root.innerHTML=landingView();return}if(!user()){if(session)logout();root.innerHTML=loginView();return}root.innerHTML=shell();renderModal();}
function loginView(){return `<div class="auth"><section class="auth-art"><div class="login-brand"><img src="assets/sizisnur-logo-mark.png" alt="Logo SiZisNur"><strong>SiZis<span>Nur</span></strong></div><div class="eyebrow">Prototype V3 • Masjid An-Nur VPA Batam</div><h1>Pengelolaan zakat, <br>lebih <em>tertata.</em></h1><p>Uji alur pembayaran, verifikasi bendahara, penilaian mustahik, perhitungan alokasi, persetujuan pengurus, dan penyaluran zakat dalam satu simulasi terintegrasi.</p><div class="pill">100% HTML + CSS + JavaScript • Berjalan offline</div><div class="login-hero-list"><div>✓ Identitas warga demo sintetis; angka Acuan Workbook 1447H ditampilkan sebagai agregat sumber.</div><div>✓ Ganti peran untuk menguji proses lintas panitia.</div><div>✓ Reset skenario demo kapan saja.</div></div></section><section class="auth-main"><div class="auth-box"><button type="button" class="login-back" data-action="back-home">← Kembali ke beranda</button><br><span class="tag info">LINGKUNGAN SIMULASI</span><h2>Masuk ke demo SiZisNur</h2><p>Pilih akun contoh sesuai panitia untuk melihat tampilan dan hak akses setiap peran. Tidak memakai password sungguhan.</p><div class="demo-roles">${db.users.filter(u=>u.tenantId==='TN-ANNUR'&&u.id!=='US-AML2').map(u=>`<button class="role-tile" data-action="quick-login" data-id="${u.id}"><b>${e(u.role)}</b><small>${e(u.name)} · Masjid An-Nur</small></button>`).join('')}${(db.platformAdmins||[]).filter(u=>u.active&&u.scope==='platform').map(u=>`<button class="role-tile platform-role-tile" data-action="quick-login" data-id="${e(u.id)}"><b>Admin SiZisNur</b><small>${e(u.name)} · Konsol tingkat root</small></button>`).join('')}</div><form data-form="login"><div class="grid-form">${sel('Akun demonstrasi','account',[...db.users.filter(u=>u.active).map(u=>[u.id,u.name+' — '+u.role+' ('+u.tenantId+')']),...(db.platformAdmins||[]).filter(u=>u.active&&u.scope==='platform').map(u=>[u.id,u.name+' — Admin SiZisNur (Konsol Root)'])])}<div class="field"><label>Opsi sesi</label><label class="check"><input type="checkbox" name="remember"> Ingat saya di perangkat ini</label></div></div>${frmBtn('Masuk ke dashboard')}</form><p class="caption"><button type="button" class="btn primary" data-v5-action="muzakki-register">Daftar akun Muzakki</button></p><p class="caption">Mode publik: ${btn('Lihat statistik & verifikasi struk','public','sm')} &nbsp; ${btn('Ajukan lembaga demo','tenant-apply','sm')} &nbsp; <span class="caption">Konsol root tersedia melalui akun Admin SiZisNur.</span></p><div class="alert warn">${DEMO_CAVEAT}</div></div></section></div><div id="modal-root"></div>`}
function renderPage(){try{switch(state.page){case'dashboard':return dashboard();case'tenant':return tenantPage();case'users':return usersPage();case'periods':return periodsPage();case'settings':return settingsPage();case'schedule':return schedulePage();case'muzakki':return muzakkiPage();case'transactions':return transactionsPage();case'deposits':return depositsPage();case'mustahik':return mustahikPage();case'allocation':return allocationPage();case'distribution':return distributionPage();case'incentives':return incentivesPage();case'reports':return reportsPage();case'workbook':return workbookPage();case'notifications':return notificationsPage();case'audit':return auditPage();case'help':return helpPage();default:return dashboard()}}catch(err){console.error(err);return `<div class="alert danger">Kesalahan tampilan: ${e(err.message)}</div>`}}
function transactionTotals(t){return {money:sum(t.lines.filter(x=>x.type==='uang'),'value'),rice:sum(t.lines.filter(x=>x.type==='beras'),'value')}}
function metrics(){let p=activePeriod()||scoped('periods')[0],t=scoped('transactions').filter(x=>x.periodId===p?.id&&x.status!=='batal'),v=t.filter(x=>x.status==='terverifikasi'),a=scoped('allocations').filter(x=>x.periodId===p?.id&&x.status==='disetujui'),aLedger=a.filter(x=>x.source!=='workbook-1447'),aWorkbook=a.filter(x=>x.source==='workbook-1447'),d=scoped('distributions').filter(x=>x.periodId===p?.id&&x.status==='tersalurkan');return {p,t,v,a,aLedger,aWorkbook,d,received:sum(t,x=>transactionTotals(x).money),rice:sum(t,x=>transactionTotals(x).rice),verified:sum(v,x=>transactionTotals(x).money),verifiedRice:sum(v,x=>transactionTotals(x).rice),allocated:sum(a,x=>allocationMoney(x)),allocatedRice:sum(a,x=>allocationRice(x)),allocatedLedger:sum(aLedger,x=>allocationMoney(x)),allocatedRiceLedger:sum(aLedger,x=>allocationRice(x)),allocatedWorkbook:sum(aWorkbook,x=>allocationMoney(x)),allocatedRiceWorkbook:sum(aWorkbook,x=>allocationRice(x)),sent:sum(d,'money'),sentRice:sum(d,'rice'),jiwa:sum(t,'jiwa'),people:new Set(t.map(x=>x.personId)).size}}
function flexibleMustahiks(){const periodId=activePeriod()?.id;const reserved=new Set(scoped('allocations').filter(a=>a.periodId===periodId&&a.status!=='ditolak').flatMap(a=>(a.items||[]).map(i=>i.mustahikId)));return scoped('mustahiks').filter(x=>x.status==='terverifikasi'&&!reserved.has(x.id))}
function dashboard(){const m=metrics(),t=m.t.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));let cats=CATEGORIES.map(cat=>({name:cat,value:sum(m.t,x=>sum(x.lines.filter(l=>l.category===cat&&l.type==='uang'),'value'))})),max=Math.max(1,...cats.map(x=>x.value));return `${boxhead('Ringkasan Pengelolaan Zakat',`Periode ${e(m.p?.name||'belum dibuka')} • Peran: ${e(user().role)}. Dashboard ini menunjukkan transaksi demo lokal; angka agregat workbook 1447H tersedia di menu Acuan Workbook.`,btn('▶ Panduan alur demo','guided','primary'))}<div class="hero"><div><h2>Assalamu’alaikum, ${e(user().name.split(' ')[0])} 👋</h2><p>Semua modul pada prototype terhubung menggunakan data lokal yang sama.<br> Lanjutkan proses sesuai kewenangan role, lalu lihat perubahan ringkasan secara langsung.</p></div>${btn(can('reports')?'Lihat laporan':'Mulai simulasi',can('reports')?'navigate':'guided','',can('reports')?'data-page="reports"':'')}</div><div class="cards">${stat('Penerimaan uang tercatat',rup(m.received),'Belum tentu seluruhnya terverifikasi','◈')}${stat('Penerimaan beras',kg(m.rice),'Pisah dari kas uang','▥')}${stat('Total muzakki',m.people+' orang',m.jiwa+' jiwa dibayarkan','♙')}${stat('Terverifikasi bendahara',rup(m.verified),'Beras: '+kg(m.verifiedRice),'✓')}</div><div class="two-col"><div class="card"><div class="card-top"><h3>Penerimaan per kategori (uang)</h3>${tag('aktif')}</div>${cats.map(c=>`<div class="bar-row"><label>${e(c.name)}</label><div class="bar"><i style="width:${Math.max(0,c.value/max*100)}%"></i></div><b>${rup(c.value)}</b></div>`).join('')}<p class="caption">Penerimaan beras dicatat terpisah dan tidak dijumlahkan sebagai rupiah.</p></div><div class="card"><h3>Status distribusi</h3><div class="mini-list"><div class="mini-item"><span>Dana terverifikasi</span><b>${rup(m.verified)}</b></div><div class="mini-item"><span>Alokasi dari transaksi demo</span><b>${rup(m.allocatedLedger)}</b></div><div class="mini-item"><span>Rencana workbook disetujui</span><b>${rup(m.allocatedWorkbook)}</b></div><div class="mini-item"><span>Realisasi penyaluran</span><b>${rup(m.sent)}</b></div><div class="mini-item"><span>Sisa dana terverifikasi *</span><b>${rup(m.verified-m.sent-m.allocatedLedger)}</b></div><div class="mini-item"><span>Mustahik diverifikasi</span><b>${scoped('mustahiks').filter(x=>x.status==='terverifikasi').length} orang</b></div></div><p class="caption">* Saldo sederhana demonstrasi. Pada sistem produksi harus memperhitungkan komitmen, penolakan, koreksi, dan pos dana secara terpisah.</p></div></div><div class="two-col"><section class="card"><div class="card-top"><h3>Transaksi terbaru</h3>${can('transactions')?btn('Buka modul','navigate','sm','data-page="transactions"'):''}</div>${table(['Nomor','Muzakki','Uang','Beras','Status'],t.slice(0,6).map(x=>[`<b class="mono">${e(x.serial)}</b>`,e(person(x.personId)?.name),rup(transactionTotals(x).money),kg(transactionTotals(x).rice),tag(x.status)]))}</section><section class="card"><h3>Perjalanan alur yang disimulasikan</h3><div class="steps">${[['1','Penerimaan'],['2','Setoran'],['3','Mustahik'],['4','Alokasi'],['5','Distribusi']].map(([n,v])=>`<div class="step"><strong>${n}</strong>${v}</div>`).join('')}</div><p class="caption">Pengurus menyetujui alokasi; Bendahara memvalidasi setoran; Admin mengelola mustahik dan perencanaan. Untuk mencoba semua tahapan, gunakan login ulang sebagai tiap role.</p>${btn('Lihat daftar langkah uji coba','guided','primary')}</section></div>`}
function tenantPage(){return `${boxhead('Profil Lembaga & Tenant','Admin dan Pengurus dapat mengubah identitas masjid, tetapi akses antartenant dibatasi pada sesi pengguna.') }<div class="two-col"><div class="card"><h3>Identitas masjid</h3><form data-form="tenant"><div class="grid-form">${fld('Nama lembaga','name',tenant().name,'text','required')}${fld('Nomor telepon','phone',tenant().phone)}${fld('Email','email',tenant().email,'email')}${fld('Wilayah RT/RW','rt',tenant().rt)}${textarea('Alamat','address',tenant().address)}</div>${frmBtn('Simpan profil lembaga')}</form></div><div class="card"><h3>Konfigurasi tenant</h3><div class="mini-list"><div class="mini-item"><span>ID tenant</span><b class="mono">${e(tenantId())}</b></div><div class="mini-item"><span>Status</span>${tag(tenant().status)}</div><div class="mini-item"><span>Pengguna aktif</span><b>${scoped('users').filter(x=>x.active).length}</b></div><div class="mini-item"><span>Periode</span><b>${scoped('periods').length}</b></div></div><div class="alert light">Isolasi pada prototype hanya berupa filter JavaScript (bukan keamanan server). Tenant B tersedia sebagai contoh untuk pemeriksaan pemisahan antarmuka.</div></div></div>`}
function usersPage(){return `${boxhead('Manajemen Akun & Role','Admin hanya mengelola akun dalam tenant yang aktif. Otorisasi ini merupakan simulasi UI.',btn('Tambah pengguna','user-new','primary'))}<div class="card">${table(['Pengguna','Email','Peran','Status','Aksi'],scoped('users').map(u=>[`<b>${e(u.name)}</b><div class="tiny mono">${e(u.id)}</div>`,e(u.email),tag(u.role),tag(u.active?'aktif':'nonaktif'),`${btn('Edit','user-edit','sm',`data-id="${u.id}"`)} ${u.id!==user().id?btn(u.active?'Nonaktifkan':'Aktifkan','user-toggle','sm',`data-id="${u.id}"`):''}`]))}</div>`}
function userModal(u){modal(u?'Edit akun':'Tambah pengguna',`<form data-form="user" data-id="${e(u?.id||'')}"><div class="grid-form">${fld('Nama lengkap *','name',u?.name||'','text','required')}${fld('Alamat email *','email',u?.email||'','email','required')}${sel('Peran','role',ROLES.map(r=>[r,r]),u?.role||'Amil')}</div><div class="alert light">Akun hanya akun demo tanpa password. Tidak ada autentikasi sesungguhnya.</div>${frmBtn()}</form>`)}
function periodsPage(){const ps=scoped('periods');return `${boxhead('Periode Pengelolaan Zakat','Hanya satu periode aktif per tenant. Arsip bersifat baca-saja secara konsep.',btn('Buat periode baru','period-new','primary'))}<div class="card">${table(['Periode','Dibuka','Ditutup','Status','Tindakan'],ps.map(p=>[`<b>${e(p.name)}</b><div class="tiny mono">${e(p.id)}</div>`,prettyDate(p.openedAt),prettyDate(p.closedAt),tag(p.status),p.status==='aktif'?btn('Tutup & arsipkan','period-close','sm danger',`data-id="${p.id}"`):p.status==='draf'?btn('Aktifkan','period-open','sm primary',`data-id="${p.id}"`):'<span class="muted">Arsip historis</span>']))}</div><div class="alert warn">Penutupan akan ditolak apabila masih terdapat setoran belum diverifikasi atau rencana alokasi menunggu persetujuan. Data tetap tersimpan untuk pelacakan; penghapusan otomatis 5–6 tahun tidak dieksekusi di prototype.</div>`}
function settingsPage(){const r=rule();return `${boxhead('Tarif & Konfigurasi Perhitungan','Seluruh tarif perhitungan zakat dikelola terpisah untuk setiap tenant. Perubahan berlaku pada transaksi baru dan tidak mengubah transaksi historis.')}<div class="two-col"><section class="card"><h3>Tarif kewajiban dan parameter syariah</h3><form data-form="rules"><div class="grid-form">${fld('Tarif zakat fitrah / jiwa (Rp)','moneyRate',r.moneyRate,'number','min="1" required')}${fld('Beras zakat fitrah / jiwa (kg)','riceRate',r.riceRate,'number','min="0.1" step="0.1" required')}${fld('Tarif fidyah / hari puasa (Rp)','fidyahRate',r.fidyahRate??65000,'number','min="1" required')}${fld('Biaya makan kafarat / orang (Rp)','kafaratMealRate',r.kafaratMealRate??r.kafaratRate??0,'number','min="0" required')}${fld('Nisab emas (gram)','nisabGoldGram',r.nisabGoldGram??85,'number','min="1" step="0.1" required')}${fld('Harga emas acuan / gram untuk maal (Rp)','goldPricePerGram',r.goldPricePerGram??1078608.56,'number','min="1" step="any" required')}${fld('Nisab zakat profesi bulanan (Rp)','professionNisabMonthly',r.professionNisabMonthly??7640144,'number','min="1" required')}${fld('Kadar zakat maal/profesi (%)','zakatRate',r.zakatRate??2.5,'number','min="0.1" max="100" step="0.1" required')}${sel('Kelipatan pembulatan alokasi (Rp)','rounding',[[1000,'Rp 1.000'],[10000,'Rp 10.000'],[50000,'Rp 50.000'],[100000,'Rp 100.000']],r.rounding)}${fld('Total insentif contoh (Rp)','monthlyIncentive',r.monthlyIncentive,'number','min="0"')}${fld('Bobot fakir (%)','fakir',r.weights.fakir,'number','min="0" max="100"')}${fld('Bobot miskin (%)','miskin',r.weights.miskin,'number','min="0" max="100"')}${fld('Bobot mualaf (%)','mualaf',r.weights.mualaf,'number','min="0" max="100"')}${fld('Ambang skor fleksibel (demo; bukan workbook)','scoreThreshold',r.scoreThreshold??'','number','min="0" placeholder="Belum disahkan"')}${textarea('Sumber/keputusan aturan dan SK wilayah','source',r.source)}</div><div class="alert light">Zakat maal memakai nisab 85 gram emas dan syarat haul satu tahun untuk harta yang mensyaratkannya. Zakat profesi memakai nisab penghasilan bulanan yang dapat diatur terpisah; mode tahunan mengalikan nilai nisab bulanan dengan 12. Fidyah memakai tarif per hari. Kafarat bergantung pada jenis pelanggaran dan tahapan syariat; biaya makan di sini hanya parameter konversi nilai yang harus disahkan pengelola dan pembimbing agama.</div>${frmBtn('Simpan tarif dan parameter tenant')}</form></section><section class="card"><h3>Catatan penerapan</h3><div class="alert warn">Nilai BAZNAS RI 1447 H/2026 M yang menjadi referensi awal adalah fitrah Rp50.000 atau 2,5 kg per jiwa dan fidyah Rp65.000 per hari. Tarif fitrah tenant yang sudah ada tidak ditimpa otomatis. Harga emas pada data demo hanya nilai awal simulasi, bukan harga pasar yang dijamin terkini; Admin wajib memperbaruinya sesuai sumber harga dan keputusan yang digunakan tenant sebelum hasil maal dipakai.</div><div class="mini-list"><div class="mini-item"><span>Nisab tahunan</span><b>${(Number(r.nisabGoldGram??85)*Number(r.goldPricePerGram??1078608.56)).toLocaleString('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0})}</b></div><div class="mini-item"><span>Nisab profesi / bulan</span><b>${Number(r.professionNisabMonthly??7640144).toLocaleString('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0})}</b></div><div class="mini-item"><span>Kadar zakat maal/profesi</span><b>${r.zakatRate??2.5}%</b></div><div class="mini-item"><span>Tarif kafarat / orang</span><b>${Number(r.kafaratMealRate??r.kafaratRate??0).toLocaleString('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0})}</b></div></div><p class="caption">Rumus digital adalah alat bantu estimasi, bukan penetapan hukum untuk semua kasus. Jenis kafarat, haul, harta yang wajib dizakati, dan cara penunaian harus diperiksa sesuai fatwa/keputusan yang berlaku.</p><p class="caption">Bobot alokasi fleksibel: ${r.weights.fakir+r.weights.miskin+r.weights.mualaf}%. Formula workbook tetap memakai batas >360 = Fakir dan >240 = Miskin; perubahan tarif tidak mengubah hasil workbook historis.</p></section></div>`}
function schedulePage(){const s=scoped('schedule'),ptg=scoped('users').filter(x=>x.role==='Amil');return `${boxhead('Jadwal & Kehadiran Amil','Jadwal, kehadiran, dan petugas pengganti menjadi dasar rekam kontribusi.',can('periods')?btn('Tambah jadwal','schedule-new','primary'):'')}<div class="card">${table(['Tanggal','Shift','Amil dijadwalkan','Pengganti','Kehadiran','Tindakan'],s.map(j=>[prettyDate(j.date),e(j.shift),e(who(j.amilId)),e(j.substituteId?who(j.substituteId):'—'),tag(j.attendance),user().role==='Admin'?btn('Ubah catatan','schedule-edit','sm',`data-id="${j.id}"`):'—']))}</div><div class="alert light">Simulasi insentif memperlihatkan kontribusi berdasarkan kehadiran dan jiwa yang dilayani. Rumus resmi harus ditetapkan sebelum digunakan.</div>`}
function scheduleModal(j){modal(j?'Ubah kehadiran dan penggantian':'Tambah jadwal',`<form data-form="schedule" data-id="${e(j?.id||'')}"><div class="grid-form">${fld('Tanggal','date',j?.date||today(),'date','required')}${sel('Jam tugas (WIB)','shift',WORKBOOK_BASELINE.shifts.map(x=>[x,x]),j?.shift||WORKBOOK_BASELINE.shifts[0])}${sel('Amil','amilId',scoped('users').filter(x=>x.role==='Amil'&&x.active).map(x=>[x.id,x.name]),j?.amilId)}${sel('Admin pengganti','substituteId',[['','Tidak ada'],...scoped('users').filter(x=>x.role==='Amil'&&x.active).map(x=>[x.id,x.name])],j?.substituteId||'')}${sel('Status hadir','attendance',['belum','hadir','tidak_hadir','digantikan'],j?.attendance||'belum')}</div>${frmBtn()}</form>`)}
function muzakkiPage(){const list=scoped('muzakki').map(m=>({...m,p:person(m.personId)})).filter(x=>x.p);return `${boxhead('Data Muzakki & Kartu Digital','Pencarian data lama, identitas kontak, kartu unik, serta histori transaksi dalam tenant.',btn('Tambah muzakki','muzakki-new','primary'))}<div class="card"><div class="card-top"><h3>Daftar muzakki (${list.length})</h3><input class="search" style="max-width:300px" id="search-muzakki" placeholder="Cari nama, HP, kode kartu…" value="${e(state.search)}" aria-label="Cari muzakki"></div><div id="muzakki-table">${muzakkiTable(list)}</div></div>`}
function muzakkiTable(list){let q=state.search.toLowerCase();const matches=list.filter(x=>(x.p.name+' '+x.p.phone+' '+x.cardCode).toLowerCase().includes(q));return table(['Nama / Kontak','Alamat','Kartu','Total transaksi','Aksi'],matches.map(x=>[`<b>${e(x.p.name)}</b><div class="tiny">${e(x.p.phone||x.p.email)}</div>`,e(x.p.address),`<span class="mono">${e(x.cardCode)}</span>`,scoped('transactions').filter(t=>t.personId===x.p.id&&t.status!=='batal').length,`${btn('Kartu','card','sm',`data-id="${x.id}"`)} ${btn('Riwayat','history','sm',`data-id="${x.p.id}"`)} ${btn('Edit','muzakki-edit','sm',`data-id="${x.id}"`)}`]))}
function muzakkiModal(m){let p=m?person(m.personId):null;modal(m?'Edit identitas muzakki':'Registrasi muzakki',`<form data-form="muzakki" data-id="${e(m?.id||'')}"><div class="grid-form">${fld('Nama lengkap *','name',p?.name||'','text','required')}${fld('Nomor HP (HP atau email wajib)','phone',p?.phone||'','tel')}${fld('Email (HP atau email wajib)','email',p?.email||'','email')}${fld('NIK (opsional, data fiktif saja)','nik',p?.nik||'','text')}${window.__SIZISNUR_DOMICILE_FIELDS?window.__SIZISNUR_DOMICILE_FIELDS(p,tenantId()):''}${textarea('Alamat lengkap *','address',p?.address||'')}</div><div class="alert light">Demi privasi, gunakan identitas dummy untuk demo. Reader e-KTP tidak diaktifkan.</div>${frmBtn('Simpan muzakki')}</form>`)}
function moneyLine(c){return `<div class="line-row"><div class="field"><label>Kategori</label><select class="line-category">${CATEGORIES.map(o=>`<option ${o===c.category?'selected':''}>${e(o)}</option>`).join('')}</select></div><div class="field"><label>Jenis</label><select class="line-type"><option value="uang" ${c.type==='uang'?'selected':''}>Uang (Rp)</option><option value="beras" ${c.type==='beras'?'selected':''}>Beras (kg)</option></select></div><div class="field"><label>Nominal / kg</label><input class="line-value" type="number" min="0.01" step="any" value="${e(c.value)}" required></div>${btn('×','remove-line','danger sm')}</div>`}
function transactionsPage(){let ps=activePeriod(),ts=scoped('transactions').filter(t=>t.periodId===(ps?.id||'')).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `${boxhead('Pencatatan Penerimaan Zakat','Penerimaan langsung oleh Amil atau Operator, dilengkapi detail kategori uang/beras dan status bendahara.',user().role==='Bendahara'?'':btn('Transaksi baru','transaction-new','primary'))}${!ps?'<div class="alert danger">Tidak ada periode aktif; petugas harus membukanya terlebih dahulu.</div>':''}<div class="card"><div class="card-top"><h3>Transaksi periode aktif (${ts.length})</h3><div class="actions">${btn('Ekspor CSV','export-tx','sm')} ${btn('Lihat simulasi QR','public','sm')}</div></div>${table(['Nomor / ID','Muzakki','Admin','Komponen','Jumlah uang','Beras','Status','Aksi'],ts.map(t=>[`<b class="mono">${e(t.serial)}</b><div class="tiny mono">${e(t.id)}</div>`,`<b>${e(person(t.personId)?.name)}</b><div class="tiny">${t.jiwa} jiwa</div>`,e(who(t.handledBy)),`<span class="tiny">${e(t.lines.map(x=>x.category).join(', '))}</span>`,rup(transactionTotals(t).money),kg(transactionTotals(t).rice),tag(t.status),`${btn('Struk / QR','receipt','sm',`data-id="${t.id}"`)} ${t.status==='tercatat'&&user().role!=='Bendahara'?btn('Batalkan','tx-cancel','sm danger',`data-id="${t.id}"`):''}`]))}</div>`}
function txModal(){const p=activePeriod();if(!p)return toast('Buka periode aktif terlebih dahulu','error');if(!state.lines?.length)state.lines=[{category:'Zakat Fitrah',type:'uang',value:''}];let mz=scoped('muzakki').map(x=>({...x,p:person(x.personId)}));let amil=scoped('users').filter(x=>x.role==='Amil'&&x.active);return modal('Catat transaksi zakat',`<form id="tx-form" data-form="transaction"><div class="grid-form">${sel('Muzakki tersimpan','existing',[['','— Muzakki baru —'],...mz.map(x=>[x.personId,x.p?.name+' · '+x.cardCode])],'')}${fld('Cari menggunakan kode kartu','cardLookup','','text','placeholder="Masukkan ID kartu, lalu klik Cari"')}<div class="full">${btn('Cari kartu & muat identitas','lookup-card','sm')}</div>${fld('Nama muzakki *','name','','text','required')}${fld('HP (atau email)','phone','','tel')}${fld('Email (atau HP)','email','','email')}${fld('Jumlah jiwa *','jiwa',1,'number','min="1" required')}${textarea('Alamat muzakki *','address','')}</div><div class="grid-form" style="margin-top:12px">${sel('Amil penerima','amilId',amil.map(x=>[x.id,x.name]),user().role==='Amil'?user().id:amil[0]?.id)}${sel('Operator pencatat','operatorId',[['','Tidak ada'],...scoped('users').filter(x=>x.role==='Operator').map(x=>[x.id,x.name])],user().role==='Operator'?user().id:'')}</div><div class="card-top" style="margin-top:22px"><h3>Rincian pembayaran</h3>${btn('+ Tambah jenis','add-line','sm')}</div><div id="tx-lines" class="line-items">${state.lines.map(moneyLine).join('')}</div><label class="check" style="margin-top:12px"><input type="checkbox" name="autoExcess" checked> Jika ada kelebihan zakat fitrah, pisahkan sebagai infak/sedekah (sesuai media pembayaran)</label><div id="tx-preview"></div>${textarea('Keterangan / catatan (opsional)','note','')}<div class="alert light">Setelah disimpan: tampilkan akad pada layar kedua (simulasi), cetak 2 rangkap, kemudian disetor bendahara. Data belum berstatus terverifikasi sampai setoran cocok.</div>${frmBtn('Simpan transaksi & tampilkan akad')}</form>`,true),updateTxPreview()}
function readLineInputs(){return [...document.querySelectorAll('#tx-lines .line-row')].map(r=>({category:r.querySelector('.line-category').value,type:r.querySelector('.line-type').value,value:num(r.querySelector('.line-value').value)}))}
function updateTxPreview(){const f=document.getElementById('tx-form');if(!f)return;let lines=readLineInputs(),j=num(f.elements.jiwa?.value),money=j*rule().moneyRate,rice=j*rule().riceRate,paidMoney=sum(lines.filter(x=>x.category==='Zakat Fitrah'&&x.type==='uang'),'value'),paidRice=sum(lines.filter(x=>x.category==='Zakat Fitrah'&&x.type==='beras'),'value');let html=`<div class="alert light" style="margin:12px 0"><b>Perhitungan fitrah otomatis (demo)</b><br> Kewajiban bila seluruh jiwa membayar dengan uang: <b>${rup(money)}</b>; bila seluruhnya beras: <b>${kg(rice)}</b>.<br> Fitrah masuk: ${rup(paidMoney)} / ${kg(paidRice)}; Total semua kategori: <b>${rup(sum(lines.filter(x=>x.type==='uang'),'value'))}</b> dan <b>${kg(sum(lines.filter(x=>x.type==='beras'),'value'))}</b>.${paidMoney&&paidRice?'<br><b>Perhatian:</b> Pembayaran campuran uang+beras harus diperiksa manual, karena jumlah jiwa per media belum dipisahkan.':''}</div>`;document.getElementById('tx-preview').innerHTML=html}
function depositsPage(){const p=activePeriod(),tr=scoped('transactions').filter(x=>x.periodId===p?.id&&x.status==='tercatat'),de=scoped('deposits').filter(x=>x.periodId===p?.id);return `${boxhead('Bendahara & Rekonsiliasi','Setoran dibandingkan dengan nilai input dan uang/beras aktual. Selisih tidak otomatis mengubah transaksi.',user().role==='Bendahara'?btn('Buat setoran dari transaksi','deposit-new','primary'):'')}<div class="cards">${stat('Transaksi belum disetor',tr.length,'Periode aktif','▤')}${stat('Setoran tertunda',de.filter(x=>x.status==='menunggu').length,'Menunggu verifikasi','◷')}${stat('Setoran berselisih',de.filter(x=>x.status==='selisih').length,'Harus diselesaikan','!')}${stat('Setoran terverifikasi',de.filter(x=>x.status==='terverifikasi').length,'Sudah cocok','✓')}</div><div class="card section-gap"><h3>Daftar setoran</h3>${table(['Kode','Amil / jumlah transaksi','Nilai sistem','Aktual uang / beras','Selisih','Status','Aksi'],de.map(s=>{let expected=depositExpected(s),dm=num(s.actualMoney)-expected.money,dr=num(s.actualRice)-expected.rice;return [`<b class="mono">${e(s.id)}</b><div class="tiny">${prettyDate(s.createdAt)}</div>`,`${e(who(s.amilId))}<div class="tiny">${s.transactionIds.length} transaksi</div>`,`${rup(expected.money)}<br>${kg(expected.rice)}`,`${rup(s.actualMoney)}<br>${kg(s.actualRice)}`,`${dm===0&&Math.abs(dr)<.001?'Cocok':`<span style="color:var(--danger)">${rup(dm)}, ${kg(dr)}</span>`}`,tag(s.status),user().role==='Bendahara'&&s.status!=='terverifikasi'?btn('Periksa','deposit-review','sm',`data-id="${s.id}"`):'—']}))}</div><div class="alert warn">Nilai transaksi asli tidak diubah oleh perubahan kas aktual. Perubahan transaksi memerlukan mekanisme koreksi dan persetujuan resmi; dalam prototype hanya ada contoh temuan dan catatan penyelesaian.</div>`}
function depositExpected(s){let t=db.transactions.filter(x=>s.transactionIds.includes(x.id)&&x.tenantId===tenantId()&&x.status!=='batal');return {money:sum(t,x=>transactionTotals(x).money),rice:sum(t,x=>transactionTotals(x).rice)}}
function depositModal(){let t=scoped('transactions').filter(x=>x.status==='tercatat'&&x.periodId===activePeriod()?.id);if(!t.length)return toast('Tidak ada transaksi yang dapat disetor','error');let amils=[...new Set(t.map(x=>x.handledBy))];modal('Buat setoran bendahara',`<form data-form="deposit-new"><div class="grid-form">${sel('Pilih amilin / petugas penerima','amilId',amils.map(x=>[x,who(x)]),amils[0])}</div><p class="caption">Sistem akan mengumpulkan semua transaksi tercatat milik amilin tersebut. Verifikasi dilakukan setelah penghitungan fisik.</p><div class="alert light" id="deposit-estimate"></div>${frmBtn('Bentuk kelompok setoran')}</form>`);updateDepositEstimate()}
function updateDepositEstimate(){const f=document.querySelector('[data-form="deposit-new"]');if(!f)return;let tx=scoped('transactions').filter(x=>x.status==='tercatat'&&x.periodId===activePeriod()?.id&&x.handledBy===f.elements.amilId.value),m=sum(tx,x=>transactionTotals(x).money),r=sum(tx,x=>transactionTotals(x).rice);document.getElementById('deposit-estimate').innerHTML=`<b>${tx.length} transaksi</b> • uang ${rup(m)} • beras ${kg(r)}`}
function depositReview(s){const a=depositExpected(s);modal('Pemeriksaan Setoran '+s.id,`<div class="cards" style="grid-template-columns:1fr 1fr">${stat('Nilai sistem',rup(a.money),kg(a.rice))}${stat('Jumlah transaksi',s.transactionIds.length,'Transaksi asli tidak berubah')}</div><form data-form="deposit-review" data-id="${s.id}"><div class="grid-form">${fld('Uang kas aktual (Rp) *','actualMoney',s.actualMoney??a.money,'number','min="0" required')}${fld('Beras aktual (kg) *','actualRice',s.actualRice??a.rice,'number','min="0" step="any" required')}${textarea('Catatan pemeriksaan / alasan selisih','note',s.note||'')}</div><div class="alert warn">Jika nilai tidak sama, status setoran menjadi <b>selisih</b> dan transaksi tetap belum terverifikasi. Perbaikan hanya pada hasil hitung aktual yang disertai alasan; nilai pembayaran asli tetap utuh.</div>${frmBtn('Simpan hasil pemeriksaan')}</form>`)}
const housingPts={'KOST':100,'KONTRAKAN':75,'MENUMPANG':50,'MILIK SENDIRI':25};
const housingOptions=[['KOST','Kost'],['KONTRAKAN','Kontrakan'],['MENUMPANG','Menumpang'],['MILIK SENDIRI','Milik sendiri']];
const depPts=v=>{const x=String(v??'').trim().toUpperCase();if(x==='4 ATAU LEBIH')return 100;const n=Number(x);return n===1?25:n===2?50:n===3?75:0};
const incomeBandPts={'NOL':100,'<1 JUTA':80,'1-2 JUTA':60,'2-3 JUTA':40,'3-4 JUTA':20,'4-5 JUTA':0,'>5 JUTA':0};
const workbookMaritalPts={'MENIKAH':25,'TIDAK MENIKAH':50,'CERAI HIDUP':75,'CERAI MATI':100};
const maritalOptions=[['MENIKAH','Menikah'],['TIDAK MENIKAH','Tidak menikah'],['CERAI HIDUP','Cerai hidup'],['CERAI MATI','Cerai mati']];
function scoreMustahik(v){
 const region=String(v.region??'').trim().toLowerCase();
 const p1=!region?0:(region==='non rw 10'?50:100);
 const p2=housingPts[String(v.housing||'').trim().toUpperCase()]??0,p3=workbookMaritalPts[String(v.marital||'').trim().toUpperCase()]??0;
 const band=String(v.incomeBand||'').trim().toUpperCase();
 const p4=incomeBandPts[band]??0,p5=depPts(v.dependents);
 return p1+p2+p3+p4+p5;
}
function classifyMustahik(score,mualafRoute){
 const p=score===0?'':score>360?'FAKIR':score>240?'MISKIN':'CUKUP LAYAK';
 const q=mualafRoute?'MUALAF':'';
 let r='CUKUP LAYAK';
 if(!q&&p==='FAKIR')r='FAKIR';
 else if(q&&p==='MISKIN')r='MISKIN';
 else if(!q&&p==='MISKIN')r='MISKIN';
 else if(q&&p==='CUKUP LAYAK')r='MUALAF';
 else if(!q&&p==='')r='';
 return {jalurFM:p,finalStatus:r};
}
function allocationMoney(a){return sum(a.items||[],'money')+num(a.balanceMoney)}
function allocationRice(a){return sum(a.items||[],'rice')+num(a.balanceRiceKg)}
function mustahikPage(){const ms=scoped('mustahiks');return `${boxhead('Mustahik, Survei & Kelayakan','Penilaian mengikuti kolom H–R LIST MUSTAHIK 2026; asnaf final dihitung dari skor dan jalur Mualaf sesuai formula workbook.',btn('Tambah survei mustahik','mustahik-new','primary'))}<div class="cards">${stat('Data mustahik demo',ms.length,'Identitas seluruhnya sintetis')}${stat('Fakir',ms.filter(x=>(x.finalStatus||x.asnaf)==='FAKIR').length,'Skor > 360')}${stat('Miskin',ms.filter(x=>(x.finalStatus||x.asnaf)==='MISKIN').length,'Skor > 240 sampai 360')}${stat('Mualaf',ms.filter(x=>(x.finalStatus||x.asnaf)==='MUALAF').length,'Jalur Mualaf sesuai formula')}</div><div class="card"><div class="card-top"><h3>Daftar calon/penerima mustahik</h3>${btn('Lihat aturan skor','show-score','sm')}</div>${table(['Nama demo','Wilayah / asnaf final','Input penilaian','Skor / jalur F/M','Status survei','Aksi'],ms.map(m=>[`<b>${e(person(m.personId)?.name)}</b><div class="tiny">${e(person(m.personId)?.address)}</div>`,`${e(m.region||m.rt)}<br><span class="tag info">${e(m.finalStatus||m.asnaf||'Belum diklasifikasi')}</span>`,`<span class="tiny">${e(m.incomeBand||'Belum diisi')} · ${e(m.housing||'—')} · ${e(m.marital||'—')}</span><div class="tiny">${e(m.dependents||'Belum diisi')} tanggungan</div>`,`<b>${num(m.score)}</b> / 500<div class="tiny">F/M: ${e(m.jalurFM||'—')} · Q: ${m.mualafRoute?'MUALAF':'—'}</div>`,tag(m.status),`${btn('Edit survei','mustahik-edit','sm',`data-id="${m.id}"`)} ${m.status!=='terverifikasi'?btn('Verifikasi','mustahik-verify','sm primary',`data-id="${m.id}"`):''}`]))}</div><div class="alert warn">Data daftar adalah sintetis untuk mereproduksi komposisi rekap sumber (cached) 21 Fakir, 103 Miskin, 5 Mualaf. Formula R row 16 akan berbeda saat dihitung ulang; lihat Acuan Workbook. Jangan gunakan identitas warga asli pada prototype lokal.</div>`}
function updateMustahikScorePreview(){
 const f=document.querySelector('[data-form="mustahik"]');if(!f)return;
 const d=getForm(f),score=scoreMustahik(d),classification=classifyMustahik(score,d.mualafRoute==='MUALAF');
 const el=document.getElementById('mustahik-score-preview');if(!el)return;
 el.innerHTML=`<b>Skor sementara: ${score} / 500</b><br>Jalur F/M (P): ${e(classification.jalurFM||'Kosong')} · Jalur Mualaf (Q): ${d.mualafRoute==='MUALAF'?'MUALAF':'Kosong'} · Final status (R): <b>${e(classification.finalStatus||'Kosong')}</b>`;
}
